function EXTRA(R,ICON){
 /* hook: the planetary hub inside a wheel, and the speed it trades for torque */
 ICON.gtHub=(x,y)=>`<g transform="translate(${x-190} ${y-85})">${GT_box(0,0,380,170,{fill:'#FFFFFF',st:GT_GREY,sw:3,r:18})}
  <circle cx="88" cy="85" r="72" fill="#343A40"/><circle cx="88" cy="85" r="56" fill="#F8F9FA"/>${GT_epi(88,85,0.78,{n:3})}
  ${GT_T(180,58,'planetary hub',{fs:24,fw:800,fill:BLU})}${GT_T(180,94,'ring fixed, sun in,',{fs:22,fill:GT_GREY})}${GT_T(180,124,'arm drives wheel',{fs:22,fill:GT_GREY})}</g>`;
 ICON.gtSpeed=(x,y)=>`<g transform="translate(${x-190} ${y-85})">${GT_box(0,0,380,170,{fill:'#FFFFFF',st:BLU,sw:3,r:18})}
  ${GT_box(14,46,92,78,{fill:'#E7F5FF',st:BLU,sw:3,r:10})}${GT_T(60,80,'motor',{fs:22,fw:800,a:'middle',fill:BLU})}${GT_T(60,108,'600 rpm',{fs:20,fw:700,a:'middle',fill:BLU})}
  ${GT_arrow(112,85,154,85,ORG,5)}${GT_T(133,68,'÷ 3.5',{fs:20,fw:800,a:'middle',fill:ORG})}
  <circle cx="206" cy="85" r="46" fill="#343A40"/><circle cx="206" cy="85" r="30" fill="#F8F9FA"/><circle cx="206" cy="85" r="7" fill="#343A40"/>
  ${GT_T(262,78,'171 rpm',{fs:22,fw:800,fill:GRN})}${GT_T(262,108,'more torque',{fs:20,fw:700,fill:GRN})}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.gtPlanet=(x,y)=>`<g transform="translate(${x-150} ${y-150})">${GT_epi(150,150,1.95,{n:3})}</g>`;
 ICON.gtSpec=(x,y)=>{const [sp,my]=GT_spec(0,10,330,280,12);return `<g transform="translate(${x-200} ${y-150})">${sp}${GT_L(0,my(GT_PEQ),340,my(GT_PEQ),GRN,5)}${GT_T(346,my(GT_PEQ)+8,'8.73',{fs:26,fw:800,fill:GRN})}${GT_L(0,my(10),340,my(10),GT_GREY,2,'stroke-dasharray="6 5"')}${GT_T(346,my(10)+4,'10',{fs:22,fill:GT_GREY})}</g>`};
 ICON.gtRays=(x,y)=>{const sp=[560,400,280,200,140,100],Y=v=>GT_lx(v,560,100,20,300),xs=[20,200,380];let s='';
  sp.forEach(v=>{s+=GT_L(0,Y(v),400,Y(v),GT_LIGHT,2)});xs.forEach(xx=>{s+=GT_L(xx,0,xx,320,GT_GREY,3)});
  [560,400,280].forEach(v=>{s+=GT_L(xs[0],Y(560),xs[1],Y(v),BLU,5)});
  [560,400,280].forEach(v=>{s+=GT_L(xs[1],Y(v),xs[2],Y(v),ORG,5)});
  [[560,200],[400,140],[280,100]].forEach(([a,bb])=>{s+=GT_L(xs[1],Y(a),xs[2],Y(bb),GRN,5)});
  sp.forEach(v=>{s+=`<circle cx="${xs[2]}" cy="${Y(v).toFixed(1)}" r="8" fill="${GT_DARK}"/>`});
  return `<g transform="translate(${x-200} ${y-160})">${s}</g>`};
}
